-- First Spanish article translations (phase 2 of the "all six languages"
-- rollout). Same 5 articles as German's first batch
-- (20261001000400_de_article_translations_batch1.sql) -- Male Airport,
-- the Gaafu Atoll fishing guide, fishing techniques, fishing seasons, and
-- "Where Is Maldives Located" -- so coverage stays even across languages
-- rather than one language racing ahead on article count while others
-- have none. Same conventions as the German batch: canonical English
-- entity_id kept, own Spanish slug/title/body, internal links inside the
-- body still point at the English URLs (those verticals aren't translated
-- yet).
-- FIX (applied after discovering the bug): entity_id below is resolved via a
-- scalar subquery on the canonical English article slug, NOT a hardcoded
-- UUID literal. nodes.id is generated by gen_random_uuid() at insert time with
-- no explicit id column in the seeding migration, so the same article gets a
-- different random UUID in every database (local sandbox vs. production). A
-- literal UUID captured from one database's nodes table will never match row
-- in another, causing translations_entity_id_fkey violations. Resolving by
-- slug instead makes this migration portable across any database that has
-- run the legacy_articles seed migration.
insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ((select id from nodes where node_type = 'article' and slug = 'male-airport-velana-international-airport'), 'article', 'es', 'aeropuerto-de-male-velana-international-airport', 'Aeropuerto de Malé | Velana International Airport', 'Descubre todo lo que necesitas saber sobre el Aeropuerto de Malé, también conocido como Velana International Airport, la principal puerta de entrada a Maldivas. Información sobre vuelos, instalaciones y más.', null, '<h2>Introducción</h2><p>El Velana International Airport, ampliamente conocido como el Aeropuerto de <a href="/maldives/islands/male/">Malé</a>, es la principal puerta de entrada internacional a las impresionantes islas de Maldivas. Situado en la isla de Hulhulé, a poca distancia de la capital, Malé, este aeropuerto es un punto neurálgico para viajeros de todo el mundo. Con instalaciones de última generación, amplia conectividad y servicios de primer nivel, el Aeropuerto de Malé desempeña un papel vital en la industria turística maldiva, gestionando millones de pasajeros al año.</p><p>Maldivas es famosa por sus playas idílicas, aguas cristalinas y resorts de lujo. Ya sea que llegues para unas vacaciones familiares, una escapada romántica o un viaje aventurero en solitario, tu travesía comienza en el Velana International Airport. Esta guía ofrece un vistazo detallado a todo lo que necesitas saber sobre el Aeropuerto de Malé, incluyendo su historia, instalaciones, opciones de transporte y consejos de viaje.</p><h4>Navegación rápida</h4><p>Resumen del aeropuerto Información de vuelos Instalaciones y servicios Transporte y accesibilidad Consejos de viaje para el Velana International Airport Mapa del aeropuerto de Maldivas Qué hacer en el aeropuerto de Maldivas Lista de aeropuertos de Maldivas Preguntas frecuentes</p><h2>Resumen del aeropuerto</h2><p>El Velana International Airport (IATA: MLE, ICAO: VRMM) es el aeropuerto más concurrido y prominente de Maldivas, y sirve como punto de entrada principal tanto para turistas internacionales como para viajeros nacionales. Su ubicación estratégica en la isla de Hulhulé, junto a la capital Malé, lo convierte en un centro esencial para el transporte aéreo en la región.</p><p>Conocido originalmente como Hulhulé Airport, fue inaugurado en 1960 y desde entonces ha pasado por varias ampliaciones y mejoras para dar cabida al creciente número de visitantes de Maldivas. En 2017, el aeropuerto fue renombrado como Velana International Airport en honor a Ibrahim Nasir, el segundo presidente de Maldivas, quien desempeñó un papel importante en el desarrollo del país. Hoy en día, el Velana International Airport cuenta con instalaciones modernas, incluida una nueva pista capaz de dar servicio a las aeronaves más grandes del mundo, como el Airbus A380.</p>', 'Aeropuerto de Malé | Velana International Airport | Guía de Viaje a Maldivas | MTG', 'Descubre todo lo que necesitas saber sobre el Aeropuerto de Malé, también conocido como Velana International Airport, la principal puerta de entrada a Maldivas. Información sobre vuelos, instalaciones y más.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'gaafu-atoll-fishing-guide-mfh-maamendhoo'), 'article', 'es', 'pesca-atolon-gaafu-guia-lodge-charter-maamendhoo', 'Pesca en el Atolón Gaafu: Guía de nuestro lodge y charter en Maamendhoo', 'El barco de charter, los precios y los paquetes de varias noches que ofrecemos desde nuestro propio lodge en Maamendhoo, Atolón Gaafu Alifu.', null, '<p>Maamendhoo, una isla en el Atolón Gaafu Alifu, en el sur de Maldivas, alberga nuestro propio lodge y la operación de charter que funciona junto a él. Esta guía cubre el barco, los precios del charter y los paquetes de varias noches creados en torno a él.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge.jpeg" alt="Maldives Fishing and Holidays Lodge, Maamendhoo, Atolón Gaafu Alifu" loading="lazy" /></figure><h2>El lodge</h2><p><a href="/maldives/guesthouses/maldives-fishing-and-holidays-lodge/">Nuestro lodge</a> es una pensión en Maamendhoo con habitaciones de pensión completa para hasta 2 huéspedes cada una, gestionada por el mismo operador que los charters de pesca — así que el alojamiento y la pesca se reservan desde un mismo lugar en lugar de organizarse por separado.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge-hotel.jpeg" alt="Maldives Fishing and Holidays Lodge" loading="lazy" /></figure><h2>El barco</h2><p>Los charters se realizan a bordo del «Emperor», un barco de pesca de 32 pies con dos motores fuera de borda de 200 CV y una capacidad máxima de 5 pasajeros.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-charter-boat.webp" alt="Barco de charter de pesca en Maldivas" loading="lazy" /></figure><h2>Precios de charter privado</h2><p>Dos charters privados se pueden reservar directamente, con precio por barco en lugar de por persona:</p><ul><li><a href="/maldives/fishing/private-full-day-fishing-charter/">Charter de pesca privado de día completo</a> — desde 1.380 USD por barco, aproximadamente 8 horas.</li><li><a href="/maldives/fishing/private-half-day-fishing-charter/">Charter de pesca privado de medio día</a> — desde 980 USD por barco, aproximadamente 4 horas.</li></ul><h2>Paquetes de pesca de varias noches</h2><p>Más allá de los dos charters independientes, el operador ofrece 14 paquetes de varias noches de 2 a 8 noches, cada uno disponible en formato de pesca de día completo o medio día, que incluyen la estancia en el lodge, un vuelo doméstico de ida y vuelta, el traslado en barco y el número correspondiente de días de charter. Los precios se escalonan según el tamaño del grupo, de 1 a 5 huéspedes compartiendo el barco, siendo 5 huéspedes quienes obtienen la mejor tarifa por persona. El <a href="/maldives/packages/2-night-maldives-fishing-package-full-day-fishing/">paquete de 2 noches</a> y el <a href="/maldives/packages/8-night-maldives-fishing-package-full-day-fishing/">paquete de 8 noches</a> marcan los dos extremos de ese rango — consulta el <a href="/maldives/packages/fishing/">listado completo de paquetes de pesca</a> para ver todas las duraciones disponibles.</p><h2>Cómo llegar</h2><p>Los paquetes creados en torno a Maamendhoo combinan un vuelo doméstico de ida y vuelta con un traslado en barco a la isla, organizado como parte del paquete en lugar de reservarse por separado.</p><h2>Reservas</h2><p>Todo lo anterior son reservas basadas en consulta previa — contáctanos a través de la <a href="/maldives/providers/maldives-fishing-and-holiday/">página del operador</a>, o empieza desde la página de charter o paquete que mejor se adapte a tu viaje.</p>', 'Pesca en el Atolón Gaafu: Guía de nuestro lodge y charter en Maamendhoo | Guía de Viaje a Maldivas | MTG', 'El barco de charter, los precios y los paquetes de varias noches que ofrecemos desde nuestro propio lodge en Maamendhoo, Atolón Gaafu Alifu.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-fishing-techniques-guide'), 'article', 'es', 'tecnicas-pesca-maldivas-curricon-jigging-popping-linea-mano', 'Técnicas de pesca en Maldivas: Curricán, jigging, popping y pesca con línea de mano explicados', 'Una guía sencilla sobre las principales técnicas de pesca utilizadas en los atolones maldivos — curricán, jigging, popping y pesca con línea de mano — y qué especies se capturan con cada una.', null, '<p>La mayoría de las excursiones de pesca que se reservan en Maldivas se engloban en un puñado de técnicas, cada una adecuada para especies y zonas de agua diferentes. Esta guía explica en qué consiste cada una y qué es probable que captures con ella.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/maldives-atoll-aerial-view.webp" alt="Vista aérea de un atolón de Maldivas" loading="lazy" /></figure><h2>Curricán (Trolling)</h2><p>El curricán consiste en arrastrar líneas con señuelos o cebo detrás de un barco en movimiento, normalmente a lo largo de los bordes de un atolón o en un desnivel de arrecife por donde pasan peces pelágicos. Es la técnica estándar para el peto — uno de los peces más rápidos del océano, capaz de alcanzar velocidades de hasta 80 km/h — y también se usa para el atún de aleta amarilla y el dorado, que suelen encontrarse cerca de restos flotantes.</p><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Peto en Maldivas" loading="lazy" /></figure><h2>Jigging</h2><p>El jigging consiste en trabajar un señuelo metálico con peso de forma vertical cerca del fondo, sobre pendientes y desniveles de arrecife profundos en lugar del agua abierta que cubre el curricán. Es el método más asociado al atún dentón, un depredador solitario y de gran combatividad que vive precisamente en este tipo de estructuras.</p><figure><img src="legacy/fishing/images/dogtooth-tuna-in-maldives.webp" alt="Atún dentón en Maldivas" loading="lazy" /></figure><h2>Popping</h2><p>El popping lanza un señuelo de superficie hacia los bordes de arrecife y canales y lo recupera en tirones bruscos y salpicantes para provocar un ataque desde la superficie en lugar de las profundidades. Es la técnica más asociada al jurel gigante, para el cual Maldivas está considerado internacionalmente uno de los mejores destinos.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/giant-trevally.webp" alt="Jurel gigante capturado pescando en Maldivas" loading="lazy" /></figure><h2>Pesca con línea de mano y pesca de fondo</h2><p>La pesca con línea de mano — carrete, línea, anzuelo y cebo, manejados a mano en lugar de lanzados y recogidos — es la técnica tradicional con la barrera de entrada más baja, ofrecida habitualmente como excursión introductoria al atardecer y sin requerir experiencia previa. También es la base de la histórica industria maldiva de pesca de bonito listado con caña y línea. La pesca de fondo, una técnica estrechamente relacionada que se practica anclado sobre estructuras de arrecife, es la forma habitual de capturar meros y pargos.</p><figure><img src="legacy/images/fishing/tuna-fish-in-maldives.webp" alt="Bonito listado en Maldivas" loading="lazy" /></figure><figure><img src="uploads/assets/uploads/fishing/images/gallery/reef-fishing-grouper.webp" alt="Mero pescado en el arrecife en Maldivas" loading="lazy" /></figure><h2>Elegir una técnica</h2><p>Si quieres una primera excursión fácil y amena, la pesca con línea de mano o una excursión al atardecer no requiere experiencia. Si buscas una especie trofeo concreta, la técnica depende del pez: curricán para peto y atún, jigging para atún dentón, popping para jurel gigante. Nuestros propios <a href="/maldives/providers/maldives-fishing-and-holiday/">charters privados</a> desde Maamendhoo cubren el curricán y la pesca de fondo a bordo del «Emperor» — consulta nuestra página de <a href="/maldives/fishing/private-full-day-fishing-charter/">charter de día completo</a>, o explora la <a href="/maldives/fishing/#fish-species">guía completa de especies de peces</a> para saber más sobre lo que podrías capturar.</p>', 'Técnicas de pesca en Maldivas: Curricán, jigging, popping y pesca con línea de mano explicados | Guía de Viaje a Maldivas | MTG', 'Una guía sencilla sobre las principales técnicas de pesca utilizadas en los atolones maldivos — curricán, jigging, popping y pesca con línea de mano — y qué especies se capturan con cada una.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-fishing-seasons-month-by-month-guide'), 'article', 'es', 'temporadas-pesca-maldivas-guia-mes-a-mes', 'Temporadas de pesca en Maldivas: Guía mes a mes', 'Cuándo buscar cada especie en los atolones de Maldivas — desde la temporada de atún y peto durante el monzón del noreste hasta la posterior temporada de jurel gigante.', null, '<p>Las condiciones de pesca en Maldivas cambian con las dos temporadas de monzón del país, y varias de las especies por las que los pescadores viajan hasta aquí tienen su propia temporada dentro de ese patrón. Esta guía expone qué es realmente más productivo y cuándo, basándose en los mismos datos de especies usados en toda nuestra <a href="/maldives/fishing/">guía de pesca de Maldivas</a>.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-liveaboard-maldives.webp" alt="Liveaboard de pesca en Maldivas" loading="lazy" /></figure><h2>Los dos monzones</h2><p>Maldivas se encuentra en un clima monzónico tropical con dos grandes temporadas. El monzón del noreste, conocido localmente como Iruvai, va aproximadamente de diciembre a abril y trae mares más calmados y menos lluvia — la ventana más predecible para salidas en barco de cualquier tipo. El monzón del suroeste, Hulhangu, va aproximadamente de mayo a noviembre, con más lluvia y aguas más agitadas en un día cualquiera, aunque las salidas se siguen realizando durante todo este periodo y algunas de las mejores especies de pesca deportiva están más activas durante esta época.</p><h2>Mejor temporada por especie</h2><p>Estos son los patrones estacionales detrás de las especies cubiertas en nuestra <a href="/maldives/fishing/#fish-species">guía de especies de peces</a>:</p><ul><li><strong>Atún de aleta amarilla</strong> — de diciembre a marzo, durante el monzón del noreste, más calmado.</li><li><strong>Peto</strong> — de diciembre a marzo, la misma ventana, capturado normalmente al curricán.</li><li><strong>Dorado (Mahi-Mahi)</strong> — de diciembre a abril, a menudo cerca de restos flotantes y FADs (dispositivos agregadores de peces).</li><li><strong>Atún dentón</strong> — de noviembre a abril, en las pendientes y desniveles de arrecife más profundos.</li><li><strong>Jurel gigante</strong> — de abril a octubre, abarcando la transición hacia el monzón del suroeste.</li><li><strong>Bonito listado</strong> — todo el año, la base de la industria tradicional de pesca con caña y línea de Maldivas.</li></ul><h2>De diciembre a abril: la temporada del monzón del noreste</h2><p>Esta es la ventana en la que el atún de aleta amarilla, el peto y el dorado están todos en temporada a la vez, y los mares más calmados hacen que los días en el agua sean más cómodos y las condiciones de curricán a lo largo de los bordes del atolón, mejores.</p><figure><img src="legacy/fishing/images/yellowfin-tuna.webp" alt="Atún de aleta amarilla en Maldivas" loading="lazy" /></figure><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Peto en Maldivas" loading="lazy" /></figure><h2>De abril a octubre: temporada de jurel gigante</h2><p>A medida que la temporada se desplaza hacia el monzón del suroeste, el jurel gigante entra en temporada. Los GT se consideran el objetivo insignia de la pesca deportiva en Maldivas, patrullando bordes de arrecife y canales y conocidos por sus ataques explosivos — el país está considerado entre los mejores destinos del mundo para jureles gigantes de tamaño trofeo.</p><figure><img src="legacy/images/fishing/giant-trevally-fish.webp" alt="Jurel gigante en Maldivas" loading="lazy" /></figure><h2>Reservar según la temporada</h2><p>Nuestra propia <a href="/maldives/providers/maldives-fishing-and-holiday/">operación de charter</a> ofrece charters privados durante todo el año desde Maamendhoo, en el Atolón Gaafu Alifu, a bordo de su barco «Emperor» — consulta nuestras páginas de <a href="/maldives/fishing/private-full-day-fishing-charter/">día completo</a> y <a href="/maldives/fishing/private-half-day-fishing-charter/">medio día</a> para precios actuales, o lee el artículo completo en nuestra <a href="/maldives/travel-guide/gaafu-atoll-fishing-guide-mfh-maamendhoo/">guía de pesca del Atolón Gaafu</a>.</p>', 'Temporadas de pesca en Maldivas: Guía mes a mes | Guía de Viaje a Maldivas | MTG', 'Cuándo buscar cada especie en los atolones de Maldivas — desde la temporada de atún y peto durante el monzón del noreste hasta la posterior temporada de jurel gigante.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'where-is-maldives-located'), 'article', 'es', 'donde-estan-ubicadas-las-maldivas', '¿Dónde están ubicadas las Maldivas?', '¿Dónde están ubicadas las Maldivas? Descubre dónde se encuentra este paraíso tropical y por qué es uno de los destinos favoritos de viajeros de todo el mundo.', null, '<h2>Una visión general de la ubicación de Maldivas</h2><p>Maldivas, oficialmente la República de Maldivas, es un paraíso tropical ubicado en el Océano Índico. Situada al suroeste de Sri Lanka y la India, Maldivas es una cadena de 26 atolones formados por más de 1.000 islas de coral. Esta hermosa nación es famosa por sus impresionantes playas de arena blanca, sus aguas turquesas cristalinas y sus vibrantes arrecifes de coral, lo que la convierte en un destino muy buscado por viajeros que buscan tranquilidad y belleza natural.</p><h2>Mapa de Maldivas</h2><h2>Coordenadas geográficas</h2><figure><img src="legacy/images/maps/maldives-location-map.webp" alt="Mapa de ubicación de Maldivas" loading="lazy" /></figure><p>Maldivas está situada estratégicamente a unos 7 grados al norte del ecuador, lo que le confiere un clima cálido y tropical durante todo el año. Las coordenadas geográficas de Maldivas son aproximadamente 3°15'' de latitud norte y 73°00'' de longitud este. Esta ubicación sitúa a Maldivas en medio del Océano Índico, lejos de cualquier gran masa continental, lo que contribuye a su atmósfera aislada y tranquila.</p><h2>Proximidad a países vecinos</h2><figure><img src="legacy/images/maps/location-of-maldives.webp" alt="Ubicación de Maldivas" loading="lazy" /></figure><p>Maldivas se encuentra a unos 700 kilómetros al suroeste de Sri Lanka y 400 kilómetros al suroeste de la India. Esta cercanía al sur de Asia hace que Maldivas sea fácilmente accesible en avión desde las principales ciudades de la región, como Colombo, Bombay y Bangalore. La capital, <a href="/maldives/islands/male/">Malé</a>, ubicada en una de las islas, sirve como principal puerta de entrada a Maldivas, con un aeropuerto internacional que conecta el país con el resto del mundo.</p><h2>Los atolones de Maldivas</h2><figure><img src="legacy/images/maps/maldives-atoll-map.webp" alt="Mapa de atolones de Maldivas" loading="lazy" /></figure><p>Maldivas está formada por 26 atolones naturales, repartidos en aproximadamente 90.000 kilómetros cuadrados. Estos atolones se dividen en 20 regiones administrativas, cada una compuesta por numerosas islas pequeñas. Lo singular de Maldivas es que su superficie terrestre es relativamente pequeña, aunque se extiende sobre una vasta área oceánica. El atolón más grande de Maldivas es el Atolón Baa, que también es una Reserva de la Biosfera de la UNESCO, conocido por su rica biodiversidad y su entorno marino prístino.</p><h2>Importancia de la ubicación de Maldivas</h2><figure><img src="legacy/images/maps/indian-ocean.webp" alt="Importancia de la ubicación de Maldivas" loading="lazy" /></figure><p>La ubicación de Maldivas es significativa por varias razones. En primer lugar, su posición cercana al ecuador garantiza un clima cálido y soleado durante todo el año, lo que la convierte en un destino perfecto para los amantes de la playa y los deportes acuáticos. En segundo lugar, el aislamiento de Maldivas en medio del Océano Índico ofrece una sensación de lejanía y exclusividad muy valorada por los turistas que buscan un escape tranquilo. Por último, las aguas oceánicas que la rodean albergan algunos de los arrecifes de coral y la vida marina más bellos del mundo, lo que convierte a Maldivas en un destino privilegiado para el esnórquel y el buceo.</p><h2>Cómo llegar a Maldivas</h2><p>Llegar a Maldivas es relativamente sencillo, con vuelos directos disponibles desde varias grandes ciudades del mundo. La mayoría de los visitantes llegan al Velana International Airport, situado en la isla de Hulhulé, cerca de la capital Malé. Desde allí, los viajeros pueden llegar a sus islas resort en lancha rápida, hidroavión o vuelo doméstico, según la distancia desde el aeropuerto. La ubicación remota de Maldivas significa que, una vez que llegas, estarás rodeado de la tranquilidad del océano, con nada más que el sonido de las olas acompañando tu estancia.</p><h2>Conclusión: Un remoto paraíso tropical</h2><p>La ubicación de Maldivas en medio del Océano Índico la convierte en un destino verdaderamente único. Su entorno geográfico, combinado con su belleza natural y su ambiente tranquilo, atrae a visitantes de todo el mundo. Ya sea que estés planeando una escapada romántica, unas vacaciones familiares o unas vacaciones llenas de aventura, Maldivas ofrece algo para todos, con el telón de fondo de uno de los lugares más hermosos de la Tierra.</p>', '¿Dónde están ubicadas las Maldivas? | Guía de Viaje a Maldivas | MTG', '¿Dónde están ubicadas las Maldivas? Descubre dónde se encuentra este paraíso tropical y por qué es uno de los destinos favoritos de viajeros de todo el mundo.', 'published', 'claude')
on conflict (entity_id, locale) do update set
  slug = excluded.slug, title = excluded.title, short_description = excluded.short_description,
  body_html = excluded.body_html, meta_title = excluded.meta_title, meta_description = excluded.meta_description,
  translation_status = excluded.translation_status, translated_by = excluded.translated_by, updated_at = now();
